const body = $input.item.json.body || {};
const studentCode = (body.student_code || '').trim();
const message = (body.message || '').trim();
let conversationId = body.conversation_id || null;

// 1. VALIDACIÓN DE CAMPOS OBLIGATORIOS
if (!studentCode) {
  return [{
    json: {
      error: true,
      status_code: 400,
      response: 'Error: Debe proporcionar el código del estudiante (student_code).'
    }
  }];
}
if (!message) {
  return [{
    json: {
      error: true,
      status_code: 400,
      response: 'Error: Debe escribir un mensaje o pregunta para el chatbot.'
    }
  }];
}

// 2. GUARDRAILS DE SEGURIDAD Y FILTRADO
if (message.length > 500) {
  return [{
    json: {
      error: true,
      status_code: 400,
      response: 'Tu mensaje excede el límite permitido de 500 caracteres. Por favor realiza una pregunta más concisa.'
    }
  }];
}

const lowerMsg = message.toLowerCase();

// Guardrail: Inyección de Prompts / Credenciales
const injectionKeywords = ['password', 'contraseña', 'api_key', 'apikey', 'secret', 'drop table', 'delete from', 'ignore previous', 'ignora las instrucciones'];
if (injectionKeywords.some(kw => lowerMsg.includes(kw))) {
  return [{
    json: {
      error: true,
      status_code: 403,
      response: 'Por razones de seguridad y privacidad, no puedo procesar consultas sobre credenciales o comandos del sistema.'
    }
  }];
}

// Guardrail: Vocabulario ofensivo / inapropiado
const offensiveKeywords = ['groseria', 'insulto', 'estupido', 'bobo', 'idiota'];
if (offensiveKeywords.some(kw => lowerMsg.includes(kw))) {
  return [{
    json: {
      error: true,
      status_code: 400,
      response: 'Por favor utiliza un lenguaje respetuoso. Estoy aquí para apoyarte en tus consultas académicas de la UNAB.'
    }
  }];
}

// 3. CLASIFICACIÓN DE INTENCIÓN SQL
let intent = 'general_chat';
if (lowerMsg.includes('aprobada') || lowerMsg.includes('pasé') || lowerMsg.includes('gané')) {
  intent = 'approved_subjects';
} else if (lowerMsg.includes('reprobada') || lowerMsg.includes('perdí') || lowerMsg.includes('perdi')) {
  intent = 'failed_subjects';
} else if (lowerMsg.includes('pendiente') || lowerMsg.includes('me falta') || lowerMsg.includes('faltan')) {
  intent = 'pending_subjects';
} else if (lowerMsg.includes('en curso') || lowerMsg.includes('viendo') || lowerMsg.includes('matriculada')) {
  intent = 'current_subjects';
} else if (lowerMsg.includes('promedio') || lowerMsg.includes('gpa') || lowerMsg.includes('acumulado')) {
  intent = 'gpa';
} else if (lowerMsg.includes('crédito') || lowerMsg.includes('credito')) {
  if (lowerMsg.includes('falta') || lowerMsg.includes('pendiente')) {
    intent = 'credits_pending';
  } else {
    intent = 'credits_approved';
  }
} else if (lowerMsg.includes('avance') || lowerMsg.includes('porcentaje')) {
  intent = 'academic_progress';
} else if (lowerMsg.includes('prerrequisito') || lowerMsg.includes('requisito')) {
  intent = 'pending_prerequisites';
} else if (lowerMsg.includes('cursar') || lowerMsg.includes('proyectar') || lowerMsg.includes('disponible')) {
  intent = 'available_subjects';
} else if (lowerMsg.includes('repetida') || lowerMsg.includes('intentos')) {
  intent = 'repeated_subjects';
} else if (lowerMsg.includes('historial') || lowerMsg.includes('calificaciones') || lowerMsg.includes('notas')) {
  intent = 'grades_history';
} else if (lowerMsg.includes('pensum') || lowerMsg.includes('plan')) {
  intent = 'assigned_plan';
} else if (lowerMsg.includes('estudiante') || lowerMsg.includes('perfil') || lowerMsg.includes('datos')) {
  intent = 'student_info';
}

return [{
  json: {
    error: false,
    student_code: studentCode,
    conversation_id: conversationId,
    message: message,
    intent: intent
  }
}];

const studentInfo = $input.first().json;
const prevData = $('Validar Parametros y Guardrails').first().json;
const intent = prevData.intent;
const studentCode = prevData.student_code;
const userMsg = prevData.message;
let convId = prevData.conversation_id || 1;

if (!studentInfo || !studentInfo.codigo_estudiante) {
  return [{
    json: {
      success: false,
      conversation_id: convId,
      student_code: studentCode,
      response: `El código de estudiante '${studentCode}' no se encuentra registrado en el sistema universitario UNAB.`,
      intent: 'student_not_found',
      source: 'postgresql',
      timestamp: new Date().toISOString()
    }
  }];
}

let responseText = '';
const nombre = studentInfo.nombre_completo;
const programa = studentInfo.nombre_programa;
const plan = studentInfo.version_plan;
const gpa = studentInfo.promedio_gpa || 0.0;
const creditos = studentInfo.creditos_aprobados_sum || 0;
const aprobadas = studentInfo.materias_aprobadas_cnt || 0;
const reprobadas = studentInfo.materias_reprobadas_cnt || 0;
const enCurso = studentInfo.materias_en_curso_cnt || 0;

switch (intent) {
  case 'approved_subjects':
    responseText = `¡Hola ${nombre}! De acuerdo con tu registro académico en ${programa} (${plan}), tienes un total de ${aprobadas} materias APROBADAS acumulando ${creditos} créditos académicos.`;
    break;
  case 'failed_subjects':
    responseText = `Hola ${nombre}. En tu historial académico registras ${reprobadas} materia(s) REPROBADA(S). Te sugerimos revisar las opciones de repetición en el próximo periodo.`;
    break;
  case 'current_subjects':
    responseText = `Hola ${nombre}. Actualmente tienes ${enCurso} materia(s) EN CURSO en el periodo lectivo vigente.`;
    break;
  case 'gpa':
    responseText = `Hola ${nombre}. Tu promedio académico acumulado (GPA) actual es de ${gpa} / 5.00 en el programa ${programa}.`;
    break;
  case 'credits_approved':
    responseText = `Hola ${nombre}. Has completado y aprobado un total de ${creditos} créditos académicos en tu plan ${plan}.`;
    break;
  case 'credits_pending':
    responseText = `Hola ${nombre}. Considerando un pensum estándar de 21 créditos DEMO, tienes aprobados ${creditos} créditos y te restan aproximadamente ${Math.max(0, 21 - creditos)} créditos pendientes.`;
    break;
  case 'academic_progress':
    const pct = ((creditos / 21) * 100).toFixed(2);
    responseText = `Hola ${nombre}. Tu avance académico actual en el programa ${programa} es del ${pct}% (${creditos} de 21 créditos DEMO del plan ${plan}).`;
    break;
  case 'pending_prerequisites':
    responseText = `Hola ${nombre}. Para tu plan ${plan}, recuerda verificar los prerrequisitos aprobando Cálculo I antes de Cálculo II, y Programación I antes de Programación II.`;
    break;
  case 'available_subjects':
    responseText = `Hola ${nombre}. Según tus asignaturas aprobadas (${aprobadas}), estás habilitado para matricular asignaturas del semestre siguiente en tu plan ${plan}.`;
    break;
  case 'student_info':
    responseText = `Estudiante: ${nombre} | Código: ${studentCode} | Programa: ${programa} | Plan Activo: ${plan} | Promedio: ${gpa} | Créditos Aprobados: ${creditos}.`;
    break;
  default:
    responseText = `¡Hola ${nombre}! Soy el Asistente Académico UNAB. Tu promedio actual es de ${gpa} y cuentas con ${creditos} créditos aprobados. ¿En qué más puedo ayudarte con tu pensum (${plan})?`;
    break;
}

return [{
  json: {
    success: true,
    conversation_id: convId,
    student_code: studentCode,
    response: responseText,
    intent: intent,
    source: 'postgresql_structured',
    timestamp: new Date().toISOString()
  }
}];
